	isHomemenu() {
		if (!this.isBrowser) {
			return;
		}

		[
			'home',
			'projects',
			'about',
			'process',
			'contact',
			'ecommerce',
			'graphics',
			'services',
			'studio',
			'website',
			'branding',
		].forEach((id) => {
			this.document.getElementById(id)?.classList.remove('active');
		});
		let currectUrl = this.baseUrl;
		var _location = this.location.path();
		// _location = _location.split('/')[1];
		if (_location == 'home' || _location == '#') {
			this.document.getElementById('home')?.classList.add('active');
			this.updateImages('.menuhome', currectUrl + '/img/home/homehover.png');
		} else if (_location.includes('projects')) {
			this.document.getElementById('projects')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('about')) {
			this.document.getElementById('about')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('process')) {
			this.document.getElementById('process')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/homewhite.png');
		} else if (_location.includes('studio')) {
			this.document.getElementById('studio')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('contact')) {
			this.document.getElementById('contact')?.classList.add('active');
			// $(".arrowimg").attr("src", currectUrl + "/img/home/contactarrow-black.svg");
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('services/branding')) {
			this.document.getElementById('branding')?.classList.add('active');
			// $(".arrowimg").attr("src", currectUrl + "/img/home/contactarrow-black.svg");
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('services/graphics')) {
			this.document.getElementById('graphics')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('services/ecommerce-web-development')) {
			this.document.getElementById('ecommerce')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('services/website-development')) {
			this.document.getElementById('website')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		} else if (_location.includes('services')) {
			this.document.getElementById('services')?.classList.add('active');
			this.updateImages('.menuhome', this.baseUrl + '/img/home/home.png');
		}
	}
	labelchange() {
		// $('.showcls').css({"display":"block","position":"relative", "pz-indexosition":"1"});
		this.toggleClass('.showcls', 'active');
		this.toggleClass('.showcls2', 'active');
		if (this.isbarcliked) {
			this.isbarcliked = false;
		} else {
			this.isbarcliked = true;
			this.ifblackbar = false;
			this.ifwhitebar = true;
			this.addClass('.navbar', 'noblack');
		}
	}
