import { Injectable, Inject, PLATFORM_ID, NgZone } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

@Injectable({
  providedIn: 'root'
})
export class LenisService {
  private lenis: any = null;
  private initialized = false;

  constructor(
    @Inject(PLATFORM_ID) private platformId: Object,
    private readonly ngZone: NgZone,
  ) {}

  /**
   * Ensures Lenis is loaded and initialized only in the browser.
   * Uses dynamic import to avoid bundle bloat and SSR issues, and drives
   * itself from GSAP's ticker so it stays in sync with the ScrollTrigger
   * instances already used across the site's animated components.
   */
  async ensureInitialized(): Promise<void> {
    if (!isPlatformBrowser(this.platformId) || this.initialized) {
      return;
    }

    try {
      const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      if (prefersReducedMotion) {
        // Respect motion sensitivity preferences - skip smooth scrolling entirely
        this.initialized = true;
        return;
      }

      const [{ default: Lenis }, { default: gsap }, { ScrollTrigger }] = await Promise.all([
        import('lenis'),
        import('gsap'),
        import('gsap/ScrollTrigger'),
      ]);

      gsap.registerPlugin(ScrollTrigger);

      this.ngZone.runOutsideAngular(() => {
        this.lenis = new Lenis({
          duration: 1.2,
          easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
          smoothWheel: true,
        });

        // Keep ScrollTrigger-driven animations (used across the site) synced with Lenis's virtual scroll
        this.lenis.on('scroll', ScrollTrigger.update);

        gsap.ticker.add((time: number) => {
          this.lenis?.raf(time * 1000);
        });
        gsap.ticker.lagSmoothing(0);

        // Lenis ships CSS (html.lenis { height: auto }) that lands only once this
        // async chunk finishes loading. Components' ScrollTriggers (e.g. the
        // recent-works parallax) are usually created before that, so their cached
        // start/end offsets go stale the moment Lenis's class flips the layout.
        // Refresh once now, and once more after late content/images settle.
        ScrollTrigger.refresh();
        setTimeout(() => ScrollTrigger.refresh(), 500);
      });

      this.initialized = true;
    } catch (error) {
      console.warn('Lenis initialization failed:', error);
    }
  }

  /**
   * Smoothly scrolls to a target using Lenis. Falls back silently if not initialized.
   */
  scrollTo(target: string | number | HTMLElement, options?: Record<string, unknown>): void {
    this.lenis?.scrollTo(target, options);
  }

  stop(): void {
    this.lenis?.stop();
  }

  start(): void {
    this.lenis?.start();
  }

  destroy(): void {
    if (this.lenis) {
      this.lenis.destroy();
      this.lenis = null;
      this.initialized = false;
    }
  }
}
